<script lang="ts">import {onMount} from "svelte";import {Pencil,Plus,X} from "@lucide/svelte";import {listSuppliers,saveSupplier,setSupplierStatus,updateSupplier} from "../lib/tauri";import type {Supplier} from "../lib/types";let suppliers=$state<Supplier[]>([]),error=$state(""),open=$state(false),busy=$state(false),name=$state(""),document=$state(""),phone=$state(""),status=$state("Ativo"),editingId=$state<number|null>(null);onMount(async()=>{try{suppliers=await listSuppliers()}catch(cause){error=cause instanceof Error?cause.message:"Falha ao carregar fornecedores"}});function create(){editingId=null;name=document=phone="";status="Ativo";open=true}function edit(item:Supplier){editingId=item.id;name=item.name;document=item.document??"";phone=item.phone??"";status=item.status;open=true}async function submit(){busy=true;try{const saved=editingId===null?await saveSupplier(name,document,phone,status):await updateSupplier(editingId,name,document,phone,status);suppliers=editingId===null?[saved,...suppliers]:suppliers.map((item)=>item.id===saved.id?saved:item);open=false}catch(cause){error=String(cause)}finally{busy=false}}async function toggle(item:Supplier){const next=item.status==="Ativo"?"Inativo":"Ativo";await setSupplierStatus(item.id,next);item.status=next;suppliers=[...suppliers]}</script>
{#if error && !suppliers.length}<div class="card card-body"><span class="badge danger">{error}</span></div>{:else}<article class="card"><div class="card-header"><div><h2>Gestão de Fornecedores</h2><p class="small muted">Dados persistidos no SQLite.</p></div><button class="button" onclick={create}><Plus size={17}/> Adicionar Fornecedor</button></div><div class="table-wrap"><table><thead><tr><th>Fornecedor</th><th>Documento</th><th>Telefone</th><th>Status</th><th>Ação</th></tr></thead><tbody>{#each suppliers as supplier}<tr><td><strong>{supplier.name}</strong></td><td>{supplier.document??"—"}</td><td>{supplier.phone??"—"}</td><td><span class:success={supplier.status==="Ativo"} class:danger={supplier.status!=="Ativo"} class="badge">{supplier.status}</span></td><td><div class="actions"><button class="button secondary" onclick={()=>edit(supplier)}><Pencil size={15}/> Editar</button><button class="button secondary" onclick={()=>toggle(supplier)}>{supplier.status==="Ativo"?"Desativar":"Ativar"}</button></div></td></tr>{/each}</tbody></table></div></article>{/if}
{#if open}<div class="modal-backdrop"><form class="modal card" onsubmit={(e)=>{e.preventDefault();submit()}}><div class="card-header"><h2>{editingId===null?"Novo fornecedor":"Editar fornecedor"}</h2><button type="button" class="icon-button" onclick={()=>open=false}><X size={18}/></button></div><div class="card-body form-grid"><label class="wide">Razão social<input class="input" required bind:value={name}/></label><label>CPF/CNPJ<input class="input" bind:value={document}/></label><label>Telefone<input class="input" bind:value={phone}/></label><label>Status<select bind:value={status}><option>Ativo</option><option>Inativo</option></select></label></div><div class="card-footer modal-actions"><button type="button" class="button secondary" onclick={()=>open=false}>Cancelar</button><button class="button" disabled={busy}>Salvar</button></div></form></div>{/if}
